from itertools import combinations

# Define the graph K_{3,3,3}
parts = [{0, 1, 2}, {3, 4, 5}, {6, 7, 8}]
edges = []
for i in range(len(parts)):
    for j in range(i+1, len(parts)):
        for u in parts[i]:
            for v in parts[j]:
                edges.append((min(u,v), max(u,v)))

edges.sort()
print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Check vertex connectivity >= 1 (graph is connected)
# Build adjacency list
adj = {i: set() for i in range(9)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

# BFS to check connectivity
visited = set()
queue = [0]
visited.add(0)
while queue:
    node = queue.pop(0)
    for neighbor in adj[node]:
        if neighbor not in visited:
            visited.add(neighbor)
            queue.append(neighbor)

print(f"Connected: {len(visited) == 9}")

# Find maximum independent set
def max_independent_set(n, edges):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    max_size = 0
    # Try all subsets
    for mask in range(1 << n):
        subset = [i for i in range(n) if mask & (1 << i)]
        is_independent = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if subset[j] in adj[subset[i]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            max_size = max(max_size, len(subset))
    return max_size

alpha = max_independent_set(9, edges)
print(f"Maximum independent set size: {alpha}")
print(f"Alpha <= 4: {alpha <= 4}")
